// DENSITY comes from the F slider (Constants dock): raise F for denser
// lines, lower it for sparser ones. F = 1 is the density this preset has
// always had. max() keeps the lines from vanishing if F is left at 0.
float DENSITY = 40.0 * max(F, 0.05);   // slider F

// WIDTH comes from the E slider: E = 1 is the width this preset has always
// had, higher values widen the bars, lower ones thin them out. The clamp
// keeps a thin line at the bottom and a gap between the bars at the top.
float EDGE = 1.0 - 0.2 * clamp(E, 0.05, 9.0);   // slider E

// TILT comes from the D slider: D = 1 keeps the lines horizontal, as this
// preset has always had them. Each unit away from 1 turns them by 90
// degrees in the x-y plane: D = 1.5 -> 45, D = 2 -> vertical, D = 0.5 -> -45.
float TILT = (D - 1.0) * 1.5707963;   // slider D
vec2 scanDir = vec2(sin(TILT), cos(TILT));

// Speed and position of the scan line
float scanSpeed = ubuf.u_time * 3.0;
float scanline = sin(dot(pModel.xy, scanDir) * DENSITY - scanSpeed);

// Makes the line crisp and bright
scanline = smoothstep(EDGE, EDGE + 0.2, scanline);

// Base = u_col2, scan glow = u_col1 (dock colors)
textureCol = mix(ubuf.u_col2, ubuf.u_col1, scanline);
